package com.yuegang.zhihui.order.application;import com.yuegang.zhihui.order.security.*;import java.util.*;import javax.sql.*;import org.springframework.beans.factory.annotation.*;import org.springframework.context.annotation.*;@Configuration(proxyBeanMethods=false)class OrderConfiguration{@Bean OrderService orderService(DataSource d){return new OrderService(d);}@Bean OrderUserResolver orderUserResolver(@Value("${ygh.internal-request.hmac-base64}")String e){byte[]k=Base64.getDecoder().decode(e);try{return new OrderUserResolver(k);}finally{Arrays.fill(k,(byte)0);}}}
